code.get_current_time:
def get_current_time(format='iso'):
    now = datetime.now()
    if format == 'iso':
        return now.strftime('%H:%M:%S')
    elif format == 'human':
        return now.strftime('%I:%M %p')
    elif format == 'unix':
        return str(int(now.timestamp()))
    return now.strftime('%H:%M:%S')

