def get_current_date(format='iso'):
    now = datetime.now()
    if format == 'iso':
        return now.strftime('%Y-%m-%d')
    elif format == 'human':
        return now.strftime('%A, %B %d, %Y')
    elif format == 'unix':
        return str(int(now.timestamp()))
    return now.strftime('%Y-%m-%d')

