def get_datetime(format='iso', timezone='local'):
    now = datetime.now()
    if format == 'iso':
        return now.isoformat()
    elif format == 'human':
        return now.strftime('%A, %B %d, %Y at %I:%M %p')
    elif format == 'unix':
        return str(int(now.timestamp()))
    return now.isoformat()
